# Try expanding each colored pixel with diamond/cross pattern
grid = [[0]*11 for _ in range(11)]

pixels = [(2, 1, 1), (6, 7, 2), (7, 5, 6), (7, 9, 3)]

for r, c, color in pixels:
    # Create diamond shape (radius 3)
    for dr in range(-3, 4):
        for dc in range(-3, 4):
            if abs(dr) + abs(dc) <= 3:
                nr, nc = r + dr, c + dc
                if 0 <= nr < 11 and 0 <= nc < 11:
                    grid[nr][nc] = color

action = {"action": "submit", "grid": grid}
print(json.dumps(action))

