grid = [[0]*11 for _ in range(11)]

pixels = [(2, 1, 1), (6, 7, 2), (7, 5, 6), (7, 9, 3)]

for r, c, color in pixels:
    # Fill 5x5 centered on the point
    half = 2
    for dr in range(-half, half + 1):
        for dc in range(-half, half + 1):
            nr, nc = r + dr, c + dc
            if 0 <= nr < 11 and 0 <= nc < 11:
                grid[nr][nc] = color

action = {"action": "submit", "grid": grid}
